diff.py.content:
"""Parse a unified diff and map changed lines onto Python functions (via ``ast``).

Only the *new* side of the diff matters: TestPilot writes tests for the code as
it exists after the change, so line numbers refer to the post-change file in the
working tree.
"""
from __future__ import annotations

import ast
import os
import re
import tokenize
from dataclasses import asdict, dataclass, field
from pathlib import Path, PurePosixPath

_HUNK = re.compile(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@")


@dataclass
class FileChange:
    """Changed lines for one file, in new-file line numbers."""

    path: str
    old_path: str | None
    added_lines: set[int] = field(default_factory=set)
    # added lines plus anchor lines around pure deletions
    touched_lines: set[int] = field(default_factory=set)
    is_new: bool = False
    is_deleted: bool = False


@dataclass
class ChangedFunction:
    path: str
    module: str
    qualname: str
    lineno: int
    end_lineno: int
    changed_lines: list[int]
    source: str
    is_method: bool

    @property
    def import_name(self) -> str:
        """Top-level name to import from ``module`` (class name for methods)."""
        return self.qualname.split(".")[0]

    def to_dict(self) -> dict:
        return asdict(self)


def _unquote_git_path(raw: str) -> str:
    """Decode Git's C-quoted filename bytes, including octal UTF-8 sequences."""
    escapes = {"a": 7, "b": 8, "t": 9, "n": 10, "v": 11, "f": 12, "r": 13,
               '"': 34, "\\": 92}
    decoded = bytearray()
    index = 1  # Opening double quote.
    while index < len(raw):
        char = raw[index]
        index += 1
        if char == '"':
            if index != len(raw) or 0 in decoded:
                raise ValueError("invalid Git-quoted diff path")
            return os.fsdecode(bytes(decoded))
        if char != "\\":
            decoded.extend(os.fsencode(char))
            continue
        if index >= len(raw):
            break
        escaped = raw[index]
        index += 1
        if escaped in escapes:
            decoded.append(escapes[escaped])
        elif (escaped in "0123" and index + 1 < len(raw)
              and all(digit in "01234567" for digit in raw[index:index + 2])):
            decoded.append(int(escaped + raw[index:index + 2], 8))
            index += 2
        else:
            raise ValueError("invalid escape in Git-quoted diff path")
    raise ValueError("unterminated Git-quoted diff path")


def _strip_path(raw: str) -> str | None:
    p = raw.split("\t")[0].strip()
    if p.startswith('"'):
        p = _unquote_git_path(p)
    if p == "/dev/null":
        return None
    if p.startswith(("a/", "b/")):
        p = p[2:]
    return p


def parse_unified_diff(text: str) -> list[FileChange]:
    """Parse ``git diff`` / ``diff -u`` output into per-file changed line sets.

    Hunk line counters are tracked so that removed lines whose content starts
    with ``-- `` are not mistaken for file headers.
    """
    files: list[FileChange] = []
    cur: FileChange | None = None
    pending_old: str | None = None
    old_left = new_left = 0
    new_ln = 0
    # Git hunk counts use LF-delimited records, not Unicode separators.
    for line in text.split("\n"):
        if cur is not None and (old_left > 0 or new_left > 0):
            if line.startswith("\\"):  # "\ No newline at end of file"
                continue
            if line.startswith("+"):
                cur.added_lines.add(new_ln)
                cur.touched_lines.add(new_ln)
                new_ln += 1
                new_left -= 1
            elif line.startswith("-"):
                # anchor a pure deletion to the surrounding new-file lines
                for anchor in (new_ln - 1, new_ln):
                    if anchor >= 1:
                        cur.touched_lines.add(anchor)
                old_left -= 1
            else:  # context line (" " prefix, or blank if whitespace was stripped)
                new_ln += 1
                new_left -= 1
                old_left -= 1
            continue
        if line.startswith("diff --git "):
            cur, pending_old = None, None
            continue
        if line.startswith("--- "):
            pending_old = _strip_path(line[4:])
            continue
        if line.startswith("+++ "):
            new_path = _strip_path(line[4:])
            cur = FileChange(
                path=new_path or pending_old or "",
                old_path=pending_old,
                is_new=pending_old is None,
                is_deleted=new_path is None,
            )
            files.append(cur)
            continue
        m = _HUNK.match(line)
        if m and cur is not None:
            old_left = int(m.group(2)) if m.group(2) is not None else 1
            new_left = int(m.group(4)) if m.group(4) is not None else 1
            new_ln = int(m.group(3))
            if new_left == 0:  # pure deletion hunk: "+N,0" means "after line N"
                new_ln += 1
    return files


def is_test_path(path: str) -> bool:
    p = PurePosixPath(path)
    return (
        "tests" in p.parts
        or "test" in p.parts
        or p.name.startswith("test_")
        or p.name.endswith("_test.py")
        or p.name == "conftest.py"
    )


def module_name(path: str) -> str:
    parts = list(PurePosixPath(path).with_suffix("").parts)
    if parts and parts[0] in ("src", "lib"):
        parts = parts[1:]
    if parts and parts[-1] == "__init__":
        parts = parts[:-1]
    return ".".join(parts)


def _iter_functions(body, prefix: str = "", in_class: bool = False):
    """Yield (qualname, node, is_method) for top-level functions and methods.

    Nested functions are attributed to their enclosing function. Functions
    defined under ``if``/``try``/``with``/``match`` blocks at module/class level count.
    """
    for node in body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            yield prefix + node.name, node, in_class
        elif isinstance(node, ast.ClassDef):
            yield from _iter_functions(node.body, prefix + node.name + ".", True)
        elif isinstance(node, ast.Match):
            for case in node.cases:
                yield from _iter_functions(case.body, prefix, in_class)
        else:
            for attr in ("body", "orelse", "finalbody"):
                sub = getattr(node, attr, None)
                if isinstance(sub, list):
                    yield from _iter_functions(sub, prefix, in_class)
            for handler in getattr(node, "handlers", None) or []:
                yield from _iter_functions(handler.body, prefix, in_class)


def functions_touching(source: str, path: str, lines: set[int], added: set[int]) -> list[ChangedFunction]:
    tree = ast.parse(source, filename=path)
    # Python physical lines use LF/CRLF/CR; other separators can be literals.
    src_lines = source.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    out: list[ChangedFunction] = []
    for qualname, node, is_method in _iter_functions(tree.body):
        start = min([node.lineno] + [d.lineno for d in node.decorator_list])
        end = node.end_lineno or node.lineno
        if not any(start <= ln <= end for ln in lines):
            continue
        out.append(
            ChangedFunction(
                path=path,
                module=module_name(path),
                qualname=qualname,
                lineno=start,
                end_lineno=end,
                changed_lines=sorted(ln for ln in added if start <= ln <= end),
                source="\n".join(src_lines[start - 1 : end]),
                is_method=is_method,
            )
        )
    return out


class DiffSourceError(ValueError):
    """A diff selects a source path outside the requested repository."""


def _source_path(repo: Path, raw: str) -> Path:
    """Resolve a relative diff path without admitting an outside source file."""
    relative = Path(raw)
    if relative.anchor or ".." in relative.parts:
        raise DiffSourceError(f"diff source must be repository-relative: {raw!r}")
    try:
        resolved = (repo / relative).resolve()
    except (OSError, RuntimeError, ValueError) as exc:
        raise DiffSourceError(f"cannot resolve diff source: {raw!r}") from exc
    if not resolved.is_relative_to(repo):
        raise DiffSourceError(f"diff source resolves outside repository: {raw!r}")
    return resolved


def changed_functions(repo: str | Path, diff_text: str, include_tests: bool = False) -> list[ChangedFunction]:
    """Return touched Python functions, rejecting selected sources outside ``repo``.

    Paths must be relative without parent traversal. Symlinks are supported
    when their resolved destination remains inside the resolved repository.
    Source encoding follows Python's BOM and encoding-cookie rules.
    """
    repo = Path(repo).resolve()
    result: list[ChangedFunction] = []
    for fc in parse_unified_diff(diff_text):
        if fc.is_deleted or not fc.path.endswith(".py"):
            continue
        if not include_tests and is_test_path(fc.path):
            continue
        f = _source_path(repo, fc.path)
        if not f.is_file():
            continue
        with tokenize.open(f) as source_file:
            source = source_file.read()
        result.extend(functions_touching(source, fc.path, fc.touched_lines, fc.added_lines))
    return result

sandbox.py.content:
"""Run pytest against a throwaway copy of a repo, with a wall-clock timeout.

Isolation is process-level only: a temp copy of the repo, a fresh process
group killed on timeout, and an environment with credential-looking variables
removed. It is NOT a security boundary against hostile code — run TestPilot in
a container/VM for untrusted repos.
"""
from __future__ import annotations

import json
import os
import shutil
import signal
import subprocess
import sys
import tempfile
import time
import xml.etree.ElementTree as ET
from dataclasses import asdict, dataclass, field
from functools import lru_cache
from pathlib import Path, PurePosixPath

IGNORE = shutil.ignore_patterns(".git", "__pycache__", ".pytest_cache", ".venv", "venv",
                                "*.pyc", ".coverage", "node_modules", ".mypy_cache")
_SECRET_MARKERS = ("KEY", "TOKEN", "SECRET", "PASSWORD", "CREDENTIAL")
_OMIT = "*/tests/*,*/test_*.py,*_test.py,*/conftest.py"


@dataclass
class CaseResult:
    nodeid: str
    outcome: str  # passed | failed | error | skipped
    message: str = ""
    generated_file: str | None = None


@dataclass
class CoverageReport:
    percent_total: float
    files: dict[str, dict[str, list[int]]] = field(default_factory=dict)

    def executed(self, path: str) -> set[int]:
        return set(self.files.get(path, {}).get("executed", []))

    def executable(self, path: str) -> set[int]:
        f = self.files.get(path, {})
        return set(f.get("executed", [])) | set(f.get("missing", []))


@dataclass
class SandboxResult:
    returncode: int | None
    timed_out: bool
    duration_s: float
    timeout_s: float
    output: str
    cases: list[CaseResult] = field(default_factory=list)
    coverage: CoverageReport | None = None
    generated_files: list[str] = field(default_factory=list)
    junit_available: bool = False

    def _count(self, outcome: str) -> int:
        return sum(1 for c in self.cases if c.outcome == outcome)

    @property
    def passed(self) -> int:
        return self._count("passed")

    @property
    def failed(self) -> int:
        return self._count("failed")

    @property
    def errors(self) -> int:
        return self._count("error")

    @property
    def skipped(self) -> int:
        return self._count("skipped")

    @property
    def generated_cases(self) -> list[CaseResult]:
        return [c for c in self.cases if c.generated_file in self.generated_files]

    def generated_counts(self) -> dict[str, int] | None:
        if not self.generated_files:
            return None
        cases = self.generated_cases
        return {"collected": len(cases),
                **{outcome: sum(c.outcome == outcome for c in cases)
                   for outcome in ("passed", "failed", "error", "skipped")}}

    @property
    def ok(self) -> bool:
        return (not self.timed_out and self.returncode == 0 and self.failed == 0
                and self.errors == 0 and self.passed > 0
                and (not self.generated_files
                     or any(c.outcome == "passed" for c in self.generated_cases)))

    def summary(self) -> str:
        if self.timed_out:
            return f"TIMEOUT after {self.timeout_s:g}s"
        text = (f"{self.passed} passed, {self.failed} failed, {self.errors} errors, "
                f"{self.skipped} skipped (rc={self.returncode})")
        generated = self.generated_counts()
        if generated is not None:
            text += (f"; generated: {generated['passed']} passed of "
                     f"{generated['collected']} collected")
        return text

    def failure_report(self, limit: int = 4000) -> str:
        parts = [self.summary()]
        generated = self.generated_counts()
        if generated is not None and generated["passed"] == 0:
            parts.append("No generated test case passed. Existing-suite passes cannot verify "
                         "the generated files. Write runnable tests and check project collection "
                         "rules, deselection and skip conditions.")
        if self.timed_out:
            parts.append("The test run exceeded the time limit and was killed. "
                         "Look for infinite loops, blocking I/O, or very slow tests.")
        for c in self.cases:
            if c.outcome in ("failed", "error"):
                parts.append(f"--- {c.outcome.upper()}: {c.nodeid}\n{c.message.strip()}")
        if not any(c.outcome in ("failed", "error") for c in self.cases):
            parts.append("--- pytest output (tail)\n" + self.output[-2000:])
        text = "\n".join(parts)
        return text if len(text) <= limit else text[: limit - 20] + "\n...[truncated]"

    def to_dict(self) -> dict:
        d = asdict(self)
        d.update(passed=self.passed, failed=self.failed, errors=self.errors,
                 skipped=self.skipped, ok=self.ok, summary=self.summary())
        d["generated"] = self.generated_counts()
        d["output"] = self.output[-3000:]
        return d


@lru_cache(maxsize=None)
def coverage_available(python: str) -> bool:
    return subprocess.run([python, "-c", "import coverage"], capture_output=True).returncode == 0


def clean_env(root: Path) -> dict[str, str]:
    env = {k: v for k, v in os.environ.items() if not any(m in k.upper() for m in _SECRET_MARKERS)}
    for k in ("PYTEST_ADDOPTS", "PYTEST_PLUGINS", "COVERAGE_PROCESS_START", "COVERAGE_FILE"):
        env.pop(k, None)
    paths = [str(root / "src")] if (root / "src").is_dir() else []
    env.update(PYTHONPATH=os.pathsep.join(paths + [str(root)]), PYTHONDONTWRITEBYTECODE="1", PYTHONHASHSEED="0")
    return env


def _run(cmd: list[str], cwd: Path, env: dict, timeout: float) -> tuple[int | None, str, bool]:
    """Collect output, with at most one extra second of POSIX timeout cleanup."""
    proc = subprocess.Popen(cmd, cwd=cwd, env=env, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT, text=True, errors="replace", start_new_session=True)
    try:
        out, _ = proc.communicate(timeout=timeout)
        return proc.returncode, out, False
    except subprocess.TimeoutExpired:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except (ProcessLookupError, AttributeError, PermissionError):
            proc.kill()
        try:
            # A detached helper may retain stdout after the target group dies.
            # POSIX communicate uses synchronous reads that we can stop and close;
            # preserve the existing Windows reader-thread cleanup behavior.
            out, _ = proc.communicate(timeout=1.0 if os.name == "posix" else None)
        except subprocess.TimeoutExpired as exc:
            # TimeoutExpired.output is bytes even in text mode. Preserve complete
            # diagnostics plus a replacement for a character cut off by the kill.
            out = (exc.output or b"").decode(proc.stdout.encoding, errors="replace")
            out = out.replace("\r\n", "\n").replace("\r", "\n")
            proc.stdout.close()
            proc.poll()  # Reap the killed leader without waiting for escaped helpers.
        return None, out or "", True


def parse_junit(path: Path) -> list[CaseResult]:
    root = ET.parse(path).getroot()
    cases: list[CaseResult] = []
    for tc in root.iter("testcase"):
        cls, name = tc.get("classname", ""), tc.get("name", "")
        nodeid = f"{cls}::{name}" if cls else name
        outcome, msg = "passed", ""
        for tag, label in (("failure", "failed"), ("error", "error"), ("skipped", "skipped")):
            el = tc.find(tag)
            if el is not None:
                outcome = label
                msg = (el.get("message") or "") + ("\n" + el.text if el.text else "")
                break
        generated_file = None
        for prop in tc.findall("./properties/property"):
            if prop.get("name") == "testpilot.generated_file":
                generated_file = prop.get("value")
                break
        cases.append(CaseResult(nodeid, outcome, msg, generated_file))
    return cases


def _parse_coverage(path: Path, work: Path) -> CoverageReport:
    data = json.loads(path.read_text())
    files = {}
    resolved = work.resolve()
    for name, info in data.get("files", {}).items():
        p = Path(name)
        if p.is_absolute():
            try:
                name = p.resolve().relative_to(resolved).as_posix()
            except ValueError:
                continue
        files[PurePosixPath(name).as_posix()] = {"executed": info.get("executed_lines", []),
                                                 "missing": info.get("missing_lines", [])}
    return CoverageReport(float(data.get("totals", {}).get("percent_covered", 0.0)), files)


def _safe_join(root: Path, rel: str) -> Path:
    p = (root / rel).resolve()
    if root.resolve() not in p.parents:
        raise ValueError(f"refusing to write outside sandbox: {rel}")
    return p


def run_pytest(repo: str | Path, extra_files: dict[str, str] | None = None, *, timeout: float = 60.0,
               python: str | None = None, coverage: bool | None = None,
               pytest_args: tuple[str, ...] = ()) -> SandboxResult:
    """Copy ``repo`` to a temp dir, add ``extra_files``, run pytest, collect results."""
    python = python or sys.executable
    use_cov = coverage_available(python) if coverage is None else coverage
    with tempfile.TemporaryDirectory(prefix="testpilot-") as td:
        tdp = Path(td)
        work = tdp / "repo"
        shutil.copytree(repo, work, ignore=IGNORE)
        for rel, content in (extra_files or {}).items():
            dest = _safe_join(work, rel)
            dest.parent.mkdir(parents=True, exist_ok=True)
            dest.write_text(content, encoding="utf-8")
        junit = tdp / "junit.xml"
        options = ["-q", "-p", "no:cacheprovider", "--rootdir", str(work), "-o", "addopts=",
              "-o", "junit_family=xunit2", f"--junitxml={junit}", *pytest_args]
        generated_files = sorted(extra_files or {})
        pt = ["-m", "pytest", *options]
        if generated_files:
            runner = tdp / "generated_pytest.py"
            manifest = tdp / "generated_files.json"
            shutil.copyfile(Path(__file__).with_name("_pytest_generated.py"), runner)
            manifest.write_text(json.dumps({str(_safe_join(work, rel)): rel for rel in generated_files}),
                                encoding="utf-8")
            pt = [str(runner), str(manifest), *options]
        data_file = tdp / ".coverage"
        if use_cov:
            cmd = [python, "-m", "coverage", "run", f"--data-file={data_file}", f"--source={work}",
                   f"--omit={_OMIT}", *pt]
        else:
            cmd = [python, *pt]
        env = clean_env(work)
        t0 = time.monotonic()
        rc, out, timed_out = _run(cmd, work, env, timeout)
        dur = time.monotonic() - t0
        junit_available = junit.exists() and not timed_out
        cases = parse_junit(junit) if junit_available else []
        cov = None
        if use_cov and not timed_out:
            # Reserve the report destination after pytest so a failed report
            # command cannot reuse a file left by the test run.
            with tempfile.TemporaryDirectory(prefix="coverage-report-", dir=tdp) as report_dir:
                cov_json = Path(report_dir) / "cov.json"
                crc, _, _ = _run([python, "-m", "coverage", "json", f"--data-file={data_file}", "-o", str(cov_json), "-q"],
                                 work, env, 60)
                # Exit 2 can mean a complete report is below configured fail_under.
                cov = _parse_coverage(cov_json, work) if crc in (0, 2) and cov_json.exists() else None
        return SandboxResult(rc, timed_out, round(dur, 3), timeout, out, cases, cov,
                             generated_files, junit_available)
